-- Mage base deck + ⟡ Infuse (Q 2026-10-19, Heihachi-style redesign).
-- Base deck = 16 new cards (MG-049..064) + 9 core Skill cards = 25. Each Style swaps 4 base cards for its 4 signature cards,
-- so the deck stays 25 under every Style (Pyromancer P5 K5 S15, Cryomancer P4 K6 S15, no Style P6 K8 S11).
-- ⟡ Infuse = the Style's element (Pyromancer 1 Ignite, Cryomancer 1 Chill). Every paid Skill card Infuses MG.infusePerS
-- after the chain (engine/styles.ts), so only cards with their own infuse action say "⟡ Infuse" in their text.
-- Every other MG card leaves the deck (in_deck false, kept for a future deck builder). Existing cards keep their dmg / cost.
-- No semicolons inside string literals (the Supabase MCP splits on them).

insert into public.cards (id, champion_id, name, source, line, type, dmg, effect, copies, sort_order, in_deck, tags, effect_json, cost, style_only) values
  ('MG-049', 'MG', 'Mana Strike', 'Q', 'Heihachi', 'P', 9, 'Before action, if you play Strike: Every Skill card in your chain +3 dmg', 1, 49, true, '{Attack,Spell}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"addDmg","target":"chain","n":3,"onlyType":"S"}]}]'::jsonb, null, null),
  ('MG-050', 'MG', 'Feedback Palm', 'Q', 'Heihachi', 'P', 6, 'After action, if opponent plays Block and has a card facing this one: Opponent loses 4 HP, ⟡ Infuse 1 (Pyromancer: 1 Ignite, Cryomancer: 1 Chill)', 1, 50, true, '{Attack,Control}', '[{"hook":"onResolve","if":[{"c":"enemyAction","a":"block"},{"c":"hasFacing"}],"do":[{"a":"loseHp","who":"enemy","n":4},{"a":"infuse","who":"enemy","n":1}]}]'::jsonb, null, null),
  ('MG-051', 'MG', 'Pure Arcana', 'Q', 'Heihachi', 'P', 9, 'Before action, if you play Strike and your chain has 2+ Skill cards: Your 3rd card +6 dmg', 1, 51, true, '{Attack,Spell}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"chainHas","who":"self","type":"S","n":2}],"do":[{"a":"addDmg","target":{"slot":3},"n":6}]}]'::jsonb, null, '!MG:2'),
  ('MG-052', 'MG', 'Equalize', 'Q', 'Heihachi', 'P', 10, 'Before action, if you don''t have more cards than the opponent: Your 2nd card +6 dmg, the opponent''s 2nd card −8 dmg', 1, 52, true, '{Attack,Control}', '[{"hook":"modify","if":[{"c":"handCompare","op":"<="}],"do":[{"a":"addDmg","target":{"slot":2},"n":6},{"a":"addDmg","target":{"enemySlot":2},"n":-8}]}]'::jsonb, null, '!MG:2'),
  ('MG-053', 'MG', 'Last Light', 'Q', 'Heihachi', 'P', 9, 'After action, if your HP is below 30%: Heal 14 (once a game)', 1, 53, true, '{Defend}', '[{"hook":"onResolve","if":[{"c":"hp","who":"self","op":"<","n":30,"pct":true}],"do":[{"a":"heal","who":"self","n":14}],"once":true}]'::jsonb, null, null),
  ('MG-054', 'MG', 'Even Odds', 'Q', 'Heihachi', 'P', 8, 'After action, if both Fields had the same number of cards: Draw 1', 1, 54, true, '{Speed}', '[{"hook":"onResolve","if":[{"c":"handCompare","op":"="}],"do":[{"a":"draw","who":"self","n":1}]}]'::jsonb, null, '!MG:1'),
  ('MG-055', 'MG', 'Ley Surge', 'Q', 'Heihachi', 'K', 9, 'Before action, if you play Strike: Your 1st card +8 dmg, the opponent''s 1st card +8 dmg, gain Shield 8 (absorbs hit dmg, lasts this turn only)', 1, 55, true, '{Attack,Defend}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"addDmg","target":{"slot":1},"n":8},{"a":"addDmg","target":{"enemySlot":1},"n":8},{"a":"status","who":"self","kind":"shield","turns":0,"n":8}]}]'::jsonb, null, null),
  ('MG-056', 'MG', 'Mana Ward', 'Q', 'Heihachi', 'K', 8, 'Before action, if you play Strike and your HP is 45% or less: Gain Parry 1 (the first hit on you this turn is parried: 0 dmg)', 1, 56, true, '{Defend}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hp","who":"self","op":"<=","n":45,"pct":true}],"do":[{"a":"status","who":"self","kind":"parry","turns":1,"n":1}]}]'::jsonb, null, '!MG:1'),
  ('MG-057', 'MG', 'Blink Barrier', 'Q', 'Heihachi', 'K', 6, 'Before action, if your HP is below 30%: Gain Shield 8 (absorbs hit dmg, lasts this turn only)', 1, 57, true, '{Defend,Hold}', '[{"hook":"modify","if":[{"c":"hp","who":"self","op":"<","n":30,"pct":true}],"do":[{"a":"status","who":"self","kind":"shield","turns":0,"n":8}]}]'::jsonb, null, '!MG:1'),
  ('MG-058', 'MG', 'Opening Salvo', 'Q', 'Heihachi', 'K', 9, 'Before action, if you play Strike and the opponent''s HP is 85% or more: This card +8 dmg', 1, 58, true, '{Attack}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"hp","who":"enemy","op":">=","n":85,"pct":true}],"do":[{"a":"addDmg","target":"this","n":8}]}]'::jsonb, null, '!MG:2'),
  ('MG-059', 'MG', 'Siphon', 'Q', 'Heihachi', 'K', 10, 'Every turn (Hold), if you play Charge and the opponent plays Block: Heal 5', 1, 59, true, '{Hold,Defend}', '[{"hook":"onHeld","if":[{"c":"selfAction","a":"charge"},{"c":"enemyAction","a":"block"}],"do":[{"a":"heal","who":"self","n":5}]}]'::jsonb, null, '!MG:1'),
  ('MG-060', 'MG', 'Ward Reader', 'Q', 'Heihachi', 'K', 8, 'After action, if you play Strike and the opponent plays Block: Draw 1', 1, 60, true, '{Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"},{"c":"enemyAction","a":"block"}],"do":[{"a":"draw","who":"self","n":1}]}]'::jsonb, null, null),
  ('MG-061', 'MG', 'Type Read', 'Q', 'Heihachi', 'K', 7, 'Before action, if you play Strike and the opponent''s Field is only Punch cards: This card +13 dmg', 1, 61, true, '{Attack}', '[{"hook":"modify","if":[{"c":"selfAction","a":"strike"},{"c":"fieldAll","who":"enemy","type":"P"}],"do":[{"a":"addDmg","target":"this","n":13}]}]'::jsonb, null, '!MG:2'),
  ('MG-062', 'MG', 'Overchannel', 'Q', 'Heihachi', 'K', 9, 'Comes into play: Draw 2, you can''t Block next turn', 1, 62, true, '{Speed}', '[{"hook":"onDraw","do":[{"a":"draw","who":"self","n":2},{"a":"status","who":"self","kind":"noBlock","turns":1}]}]'::jsonb, null, null),
  ('MG-063', 'MG', 'Mind Rend', 'Q', 'Heihachi', 'S', 14, 'After action, if you play Strike: Opponent discards their 2 newest cards from the Field to the bottom of their deck (Cut)', 1, 63, true, '{Spell,Control}', '[{"hook":"onResolve","if":[{"c":"selfAction","a":"strike"}],"do":[{"a":"cut","which":"newest","n":2}]}]'::jsonb, 3, null),
  ('MG-064', 'MG', 'Arcane Bait', 'Q', 'Heihachi', 'S', 8, 'Comes into play: Opponent gains Shield 14 (absorbs hit dmg, lasts through next turn) and can''t Block next turn', 1, 64, true, '{Spell,Control}', '[{"hook":"onDraw","do":[{"a":"status","who":"enemy","kind":"shield","turns":1,"n":14},{"a":"status","who":"enemy","kind":"noBlock","turns":1}]}]'::jsonb, 1, null)
on conflict (id) do update set name = excluded.name, source = excluded.source, line = excluded.line, type = excluded.type, effect = excluded.effect, effect_json = excluded.effect_json, style_only = excluded.style_only, in_deck = excluded.in_deck, tags = excluded.tags, sort_order = excluded.sort_order;

-- core Skill cards: in the deck under every Style
update public.cards set in_deck = true, style_only = null where id in ('MG-001', 'MG-002', 'MG-003', 'MG-005', 'MG-006', 'MG-013', 'MG-019', 'MG-020', 'MG-024');
-- Style signature cards (base cards they replace carry '!MG:1' / '!MG:2' above)
update public.cards set in_deck = true, style_only = 'MG:1' where id in ('MG-028', 'MG-030', 'MG-031', 'MG-032');
update public.cards set in_deck = true, style_only = 'MG:2' where id in ('MG-042', 'MG-043', 'MG-044', 'MG-048');
-- every other Mage card leaves the deck (style_only unchanged)
update public.cards set in_deck = false where champion_id = 'MG' and id not in ('MG-001', 'MG-002', 'MG-003', 'MG-005', 'MG-006', 'MG-013', 'MG-019', 'MG-020', 'MG-024', 'MG-028', 'MG-030', 'MG-031', 'MG-032', 'MG-042', 'MG-043', 'MG-044', 'MG-048', 'MG-049', 'MG-050', 'MG-051', 'MG-052', 'MG-053', 'MG-054', 'MG-055', 'MG-056', 'MG-057', 'MG-058', 'MG-059', 'MG-060', 'MG-061', 'MG-062', 'MG-063', 'MG-064');

-- Style text: ⟡ Infuse replaces Touch of Flame (Pyromancer) and Deep Freeze (Cryomancer). {MG.infusePerS} = class tuning key.
-- Each update only fires on the old text, so it runs once.
update public.champion_styles set effect = $t$⟡ Infuse: every Skill card you paid for gives the opponent {MG.infusePerS} Ignite, even when it is Blocked (each stack burns {igniteFlat} HP + {ignitePctMaxHp}% Max HP every turn and cuts heals {healCutPerStack}%, max {healCutMax}%, {igniteTurns} turns, max {igniteMax} stacks). Molten Shield: when you Block with Mana, spend up to {moltenMaxMana} Mana for Shield {moltenShieldPerMana} per Mana this turn. Each hit your Block stops gives the attacker 1 Ignite.$t$
where champion_id = 'MG' and slot = 1 and effect like 'Touch of Flame:%';
update public.champion_styles set effect = $t$Frost Armor: start the game with Shield {frostArmorShield}. Every hit a Shield soaks gives the attacker 1 Chill. ⟡ Infuse: every Skill card you paid for gives the opponent {MG.infusePerS} Chill, even when it is Blocked. Frozen Tomb (once a game): when you drop below {tombHpPct}% HP (the red bar), or would be knocked out (you stay on 1 HP), you are sealed in ice: Frost Armor's Shield {frostArmorShield} comes back and next turn you can only Block. At the end of that turn heal {tombHeal} + {tombHealPerMana} per Mana (all your Mana is spent). The turn after, {tombMeltPct}% of the Shield you have left turns into HP. Chill: each stack makes that side's hits deal {chillDmgCut}% less ({chillTurns} turns, max {chillMax}). At {chillMax} stacks the opponent is Frozen: Chill clears, Shatter takes {shatterPct}% of their Max HP and they can't Strike next turn. Absolute Zero (S + S + S all clean): the opponent is Frozen and can't Block next turn.$t$
where champion_id = 'MG' and slot = 2 and effect like '%Deep Freeze:%';
